HUBSTYLE = ('<style>main{max-width:1500px}.list{grid-template-columns:repeat(4,1fr);gap:18px}.c img{height:auto;aspect-ratio:4/3}.c b{font-size:19px}'
            '@media(max-width:900px){.list{grid-template-columns:repeat(2,1fr);gap:12px}.c b{font-size:16px}}</style>')
def _n(ims): return f'{len(ims)} photo' + ('s' if len(ims) > 1 else '')
def _cards(sec): return ''.join(
    f'<a class="c" href="/reno-{sl}.html"><img loading="lazy" src="{img(ims[0],480)[0]}" alt="{html.escape(t)}, Reno, Nevada"><b>{html.escape(t)}</b><i>{html.escape(k)}</i><span>{html.escape(sub)} · {_n(ims)}</span></a>'
    for s_, sl, t, k, sub, ims, en, kh in RENO if s_ == sec)
RURL = 'https://www.angkorlens.com/reno-lake-tahoe.html'; SF_URLS.append(RURL)
rd = 'Photos of Reno, Nevada by Samnang Loy: the Reno Arch, the Truckee River, the glass whale, neon nights and the drive there through hills and snowy mountains.'
rld = {"@context": "https://schema.org", "@type": "CollectionPage", "name": "Reno, Nevada Through My Lens", "description": rd, "url": RURL,
       "hasPart": [{"@type": "ImageGallery", "name": r[2], "url": f"https://www.angkorlens.com/reno-{r[1]}.html"} for r in RENO]}
BANDCSS = (".band{background:#B9532F;color:#fff;padding:34px 16px 120px}.bi{max-width:1500px;margin:0 auto}.band .crumb a{color:#FBE7C6}.band small{letter-spacing:.2em;font-weight:800;font-size:14px}"
 ".band h1{font-family:Georgia,serif;font-size:clamp(34px,6vw,64px);margin:6px 0 4px;color:#fff}.band h1 em{display:block;color:#FBE7C6;font-style:italic}.km2{color:#FBE7C6;font-size:20px;margin:0 0 10px}.bd{max-width:900px;font-size:17px;margin:0}"
 "h2.rh{font-family:Georgia,serif;margin:0 0 14px;padding:10px 16px;background:#fff;border-radius:12px;display:inline-block;box-shadow:0 4px 14px rgba(0,0,0,.08)}main.rm{max-width:1500px;margin-top:-100px;padding-top:0}")
_band = ('<div class="band"><div class="bi"><p class="crumb"><a href="/">Home</a> › Reno &amp; Lake Tahoe</p><small>ON THE ROAD · តាមផ្លូវ</small>'
         '<h1>Reno, Nevada <em>&amp; the road there</em></h1><p class="km2">ទីក្រុង Reno រដ្ឋ Nevada និងផ្លូវទៅដល់ទីនោះ</p>'
         '<p class="bd">Photos from Reno, “The Biggest Little City in the World,” and from my drive there: the river, neon lights, public art, green and golden hills, open wetlands, high desert and snow-capped mountains. Tap a place to see all its photos.<br>'
         'រូបថតក្នុងទីក្រុង Reno និងតាមផ្លូវ៖ ទន្លេ ភ្លើងនីអុង សិល្បៈសាធារណៈ វាលភក់ ភ្នំបៃតង វាលខ្សាច់ និងភ្នំគ្របដោយព្រិល។ ចុចលើកន្លែងណាមួយ ដើម្បីមើលរូបទាំងអស់។</p></div></div><main class="rm">')
out['reno-lake-tahoe.html'] = head('Reno, Nevada – Photos of the City & the Road There | AngkorLens', rd, RURL, img('reno-1.jpg', 1200)[0], rld).replace('<main>', _band, 1) + f'''
{HUBSTYLE}<style>{BANDCSS}</style>
<h2 class="rh">In Reno · ក្នុងទីក្រុង Reno</h2><div class="list">{_cards('In Reno')}</div>
<h2 class="rh" style="margin-top:40px">On the way · តាមផ្លូវ</h2><div class="list">{_cards('On the way')}</div>
<p class="by" style="margin-top:18px">Photographs by Samnang Loy · AngkorLens. Lake Tahoe photos coming soon.</p>
<a class="cta" href="/">← Back to AngkorLens</a></main><footer>© AngkorLens · Samnang Loy</footer></body></html>'''
for s_, sl, t, k, sub, ims, en, kh in RENO:
    u = f'https://www.angkorlens.com/reno-{sl}.html'; SF_URLS.append(u)
